sysauto_script.script:
(function() {
    // === Fetch Access Token ===
    var tokenGR = new GlideRecord("u_cisco_secure_access_token");
    tokenGR.orderByDesc("sys_created_on");
    tokenGR.setLimit(1);
    tokenGR.query();

    if (!tokenGR.next()) {
        gs.error("No access token found");
        return;
    }

    var accessToken = tokenGR.getValue("u_access_token");
    if (!accessToken) {
        gs.error("Access token is empty");
        return;
    }

    // === Query u_destinations where u_destination_id is empty ===
    var gr = new GlideRecord("u_cisco_secure_access_destinations");
    gr.addNullQuery("u_destination_id");
    gr.query();

    while (gr.next()) {
        var destName = gr.getValue("u_destination");            
        var listSysId = gr.getValue("u_destination_list_id");

        // Look up actual Cisco List ID from u_destination_list table
        var listId = null;
        var listGR = new GlideRecord("u_cisco_secure_access_destination_list");
        if (listGR.get(listSysId)) {
            listId = listGR.getValue("u_list_id");   // Cisco List ID
        }

        if (!listId) {
            gs.warn("Skipping '" + destName + "' because no Cisco list ID is available.");
            continue;
        }


        try {
            var foundId = null;
            var page = 1;
            var hasMore = true;

            while (hasMore && !foundId) {
                var r = new sn_ws.RESTMessageV2();
                r.setEndpoint("https://api.sse.cisco.com/policies/v2/destinationlists/" + listId + "/destinations");
                r.setHttpMethod("GET");
                r.setRequestHeader("Authorization", "Bearer " + accessToken);
                r.setQueryParameter("limit", "100");
                r.setQueryParameter("page", page.toString());

                var response = r.execute();
                var status = response.getStatusCode();
                var body = response.getBody();

                if (status == 200) {
                    var parsed = JSON.parse(body);

                    if (parsed.data && parsed.data.length > 0) {
                        for (var i = 0; i < parsed.data.length; i++) {
                            var item = parsed.data[i];

                            if (item.destination && item.destination.toLowerCase().trim() === destName.toLowerCase().trim()) {
                                foundId = item.id;
                                break;
                            }
                        }

                        // check if more pages exist
                        hasMore = (parsed.meta && parsed.meta.totalPages && page < parsed.meta.totalPages);
                        page++;
                    } else {
                        hasMore = false;
                    }
                } else {
                    gs.error("API call failed for destination '" + destName + "' in list " + listId +
                             " | Status: " + status + " | Body: " + body);
                    hasMore = false;
                }
            }

            if (foundId) {
                gr.u_destination_id = String(foundId).replace(/,/g, "");
                gr.update();
                gs.info("Updated destination '" + destName + "' with ID: " + foundId);
            } else {
                gs.warn("No match found in list " + listId + " for destination: " + destName);
            }

        } catch (e) {
            gs.error("Exception while fetching destination '" + destName + "' | " + (e.message || e.toString()));
        }
    }
})();
